def lps(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Create a table in bottom-up manner
    for i in range(n):
        dp[i][i] = 1  # Every single character is a palindrome of length 1

    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

